function redeemLender(uint256 id, uint256 amount) external override isRedeemable(id) returns (uint256 reward) {
        require(_tby.balanceOf(msg.sender, id) >= amount, Errors.InsufficientBalance());

        uint256 totalSupply = _tby.totalSupply(id);
        reward = (_tbyLenderReturns[id] * amount) / totalSupply;
        require(reward > 0, Errors.ZeroRewards());

        _idToCollateral[id].assetAmount -= uint128(reward);
        _tbyLenderReturns[id] -= reward;
        _tby.burn(id, msg.sender, amount);

        emit LenderRedeemed(msg.sender, id, reward);
        IERC20(_asset).safeTransfer(msg.sender, reward);
    }
function _takeSpread(uint256 rate, uint128 tbySpread) internal pure returns (uint256) {
        if (rate > Math.WAD) {
            uint256 yield = rate - Math.WAD;
            return Math.WAD + yield.mulWad(tbySpread);
        }
        return rate;
    }
function _rwaPrice() private view returns (uint256) {
        RwaPriceFeed memory priceFeed = _rwaPriceFeed;
        (, int256 answer,, uint256 updatedAt,) = AggregatorV3Interface(priceFeed.priceFeed).latestRoundData();

        // Validate the latest round data from the price feed.
        require(answer > 0, Errors.InvalidPriceFeed());
        require(updatedAt >= block.timestamp - priceFeed.updateInterval, Errors.OutOfDate());

        uint256 scaler = 10 ** (18 - priceFeed.decimals);
        return uint256(answer) * scaler;
    }
function getRate(uint256 id) public view override returns (uint256) {
        TbyMaturity memory maturity = _idToMaturity[id];
        RwaPrice memory rwaPrice = _tbyIdToRwaPrice[id];

        if (rwaPrice.startPrice == 0) {
            revert Errors.InvalidTby();
        }
        // If the TBY has not started accruing interest, return 1e18.
        if (block.timestamp <= maturity.start) {
            return Math.WAD;
        }

        // If the TBY has matured, and is eligible for redemption, calculate the rate based on the end price.
        uint256 price = rwaPrice.endPrice != 0 ? rwaPrice.endPrice : _rwaPrice();
        uint256 rate = (uint256(price).divWad(uint256(rwaPrice.startPrice)));
        return _takeSpread(rate, rwaPrice.spread);
    }

business_flow_context:
function totalSupply(uint256 id) external view returns (uint256) {
        return _totalSupply[id];
    }
function asset() external view returns (address) {
        return _asset;
    }
function burn(uint256 id, address account, uint256 amount) external onlyBloom {
        _totalSupply[id] -= amount;
        _burn(account, id, amount);
        emit Burn(account, id, amount);
    }
function tby() external view returns (address) {
        return address(_tby);
    }
function tby() external view returns (address) {
        return address(_tby);
    }
function decimals() external view returns (uint8) {
        return _decimals;
    }
function rwa() external view returns (address) {
        return _rwa;
    }
function spread() external view override returns (uint256) {
        return _spread;
    }
function uri(uint256 /*id*/ ) public view virtual override returns (string memory) {
        return "https://bloom.garden/live";
    }
function rwa() external view returns (address) {
        return _rwa;
    }
function tby() external view returns (address) {
        return address(_tby);
    }

content:
function mint(uint256 id, address account, uint256 amount) external onlyBloom {
        _totalSupply[id] += amount;
        _mint(account, id, amount, "");
        emit Mint(account, id, amount);
    }

contract_code:
{
    using Math for uint256;

    /*///////////////////////////////////////////////////////////////
                                Storage    
    //////////////////////////////////////////////////////////////*/

    /// @notice Address of the BloomPool contract.
    address private immutable _bloomPool;

    /// @notice The number of decimals for the token.
    uint8 private immutable _decimals;

    /// @notice Mapping of the user's total supply of LTby.
    mapping(uint256 => uint256) private _totalSupply;

    /*///////////////////////////////////////////////////////////////
                                Modifiers    
    //////////////////////////////////////////////////////////////*/

    modifier onlyBloom() {
        require(msg.sender == _bloomPool, Errors.NotBloom());
        _;
    }

    /*///////////////////////////////////////////////////////////////
                            Constructor    
    //////////////////////////////////////////////////////////////*/

    constructor(address bloomPool_, uint8 decimals_) {
        _bloomPool = bloomPool_;
        _decimals = decimals_;
    }

    /*///////////////////////////////////////////////////////////////
                            Functions
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Mints Tby tokens to an account.
     * @param id The Tby id.
     * @param account The address of the account to mint to.
     * @param amount The amount to mint.
     */
    function mint(uint256 id, address account, uint256 amount) external onlyBloom {
        _totalSupply[id] += amount;
        _mint(account, id, amount, "");
        emit Mint(account, id, amount);
    }

    /**
     * @notice Burns Tby tokens from an account.
     * @param id The Tby id.
     * @param account The address of the account to burn from.
     * @param amount The amount to burn.
     */
    function burn(uint256 id, address account, uint256 amount) external onlyBloom {
        _totalSupply[id] -= amount;
        _burn(account, id, amount);
        emit Burn(account, id, amount);
    }

    /// @inheritdoc ITby
    function bloomPool() external view returns (address) {
        return _bloomPool;
    }

    /// @inheritdoc ITby
    function name() external pure returns (string memory) {
        return "Term Bound Yield";
    }

    /// @inheritdoc ITby
    function symbol() external pure returns (string memory) {
        return "TBY";
    }

    /// @inheritdoc ITby
    function decimals() external view returns (uint8) {
        return _decimals;
    }

    /// @inheritdoc ITby
    function totalSupply(uint256 id) external view returns (uint256) {
        return _totalSupply[id];
    }

    /// @inheritdoc ERC1155
    function uri(uint256 /*id*/ ) public view virtual override returns (string memory) {
        return "https://bloom.garden/live";
    }
}

