function totalSupply(uint256 id) external view returns (uint256) {
        return _totalSupply[id];
    }
function asset() external view returns (address) {
        return _asset;
    }
function burn(uint256 id, address account, uint256 amount) external onlyBloom {
        _totalSupply[id] -= amount;
        _burn(account, id, amount);
        emit Burn(account, id, amount);
    }
function tby() external view returns (address) {
        return address(_tby);
    }
function tby() external view returns (address) {
        return address(_tby);
    }
function decimals() external view returns (uint8) {
        return _decimals;
    }
function rwa() external view returns (address) {
        return _rwa;
    }
function spread() external view override returns (uint256) {
        return _spread;
    }
function uri(uint256 /*id*/ ) public view virtual override returns (string memory) {
        return "https://bloom.garden/live";
    }
function rwa() external view returns (address) {
        return _rwa;
    }
function tby() external view returns (address) {
        return address(_tby);
    }

