function _setStartPrice(uint256 id, uint256 currentPrice, uint256 rwaAmount, uint256 existingCollateral) private {
        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        uint256 startPrice = rwaPrice.startPrice;
        if (startPrice == 0) {
