        uint256 tbyTotalSupply = _tby.totalSupply(id);
        uint256 tbyAmount = percentSwapped != Math.WAD ? tbyTotalSupply.mulWadUp(percentSwapped) : tbyTotalSupply;
        require(tbyAmount > 0, Errors.ZeroAmount());

