function spread() external view override returns (uint256) {
        return _spread;
    }

contract_code:
{
    /*///////////////////////////////////////////////////////////////
                                Storage    
    //////////////////////////////////////////////////////////////*/

    /// @notice Addresss of the lTby token
    Tby internal _tby;

    /// @notice Leverage value for the borrower. scaled by 1e18 (20x leverage == 20e18)
    uint256 internal _leverage;

    /// @notice The spread between the rate of the TBY and the rate of the RWA token.
    uint256 internal _spread;

    /// @notice Mapping of KYCed borrowers.
    mapping(address => bool) internal _borrowers;

    /// @notice Mapping of KYCed market makers.
    mapping(address => bool) internal _marketMakers;

    /*///////////////////////////////////////////////////////////////
                        Constants & Immutables
    //////////////////////////////////////////////////////////////*/

    /// @notice Address of the underlying asset of the Pool.
    address internal immutable _asset;

    /// @notice Decimals of the underlying asset of the Pool.
    uint8 internal immutable _assetDecimals;

    /// @notice Address of the RWA token of the Pool.
    address internal immutable _rwa;

    /// @notice Decimals of the RWA token of the Pool.
    uint8 internal immutable _rwaDecimals;

    /// @notice Scaling factor for the underlying asset.
    uint256 internal immutable _assetScalingFactor;

    /// @notice Scaling factor for the RWA token.
    uint256 internal immutable _rwaScalingFactor;

    /// @notice The upper bound leverage allowed for pool (Cant be set to 100x but just under).
    uint256 constant MAX_LEVERAGE = 100e18;

    /// @notice Minimum spread between the TBY rate and the rate of the RWA's price appreciation.
    uint256 constant MIN_SPREAD = 0.85e18;

    /*///////////////////////////////////////////////////////////////
                            Modifiers    
    //////////////////////////////////////////////////////////////*/

    modifier KycBorrower() {
        require(isKYCedBorrower(msg.sender), Errors.KYCFailed());
        _;
    }

    modifier KycMarketMaker() {
        require(isKYCedMarketMaker(msg.sender), Errors.KYCFailed());
        _;
    }

    /*///////////////////////////////////////////////////////////////
                            Constructor    
    //////////////////////////////////////////////////////////////*/

    constructor(address asset_, address rwa_, uint256 initLeverage, uint256 initSpread, address owner_)
        Ownable(owner_)
    {
        _asset = asset_;
        _rwa = rwa_;

        uint8 decimals = IERC20Metadata(asset_).decimals();
        _tby = new Tby(address(this), decimals);

        _assetDecimals = decimals;
        _rwaDecimals = IERC20Metadata(rwa_).decimals();

        _assetScalingFactor = 10 ** (18 - _assetDecimals);
        _rwaScalingFactor = 10 ** (18 - _rwaDecimals);

        _setLeverage(initLeverage);
        _setSpread(initSpread);
    }

    /*///////////////////////////////////////////////////////////////
                            Functions    
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Whitelists an address to be a KYCed borrower.
     * @dev Only the owner can call this function.
     * @param account The address of the borrower to whitelist.
     * @param isKyced True to whitelist, false to remove from whitelist.
     */
    function whitelistBorrower(address account, bool isKyced) external onlyOwner {
        _borrowers[account] = isKyced;
        emit BorrowerKyced(account, isKyced);
    }

    /**
     * @notice Whitelists an address to be a KYCed borrower.
     * @dev Only the owner can call this function.
     * @param account The address of the borrower to whitelist.
     * @param isKyced True to whitelist, false to remove from whitelist.
     */
    function whitelistMarketMaker(address account, bool isKyced) external onlyOwner {
        _marketMakers[account] = isKyced;
        emit MarketMakerKyced(account, isKyced);
    }

    /**
     * @notice Updates the leverage for future borrower fills
     * @dev Leverage is scaled to 1e18. (20x leverage = 20e18)
     * @param leverage Updated leverage
     */
    function setLeverage(uint256 leverage) external onlyOwner {
        _setLeverage(leverage);
    }

    /**
     * @notice Updates the spread between the TBY rate and the RWA rate.
     * @param spread_ The new spread value.
     */
    function setSpread(uint256 spread_) external onlyOwner {
        _setSpread(spread_);
    }

    /// @inheritdoc IPoolStorage
    function tby() external view returns (address) {
        return address(_tby);
    }

    /// @inheritdoc IPoolStorage
    function asset() external view returns (address) {
        return _asset;
    }

    /// @inheritdoc IPoolStorage
    function assetDecimals() external view override returns (uint8) {
        return _assetDecimals;
    }

    /// @inheritdoc IPoolStorage
    function rwa() external view returns (address) {
        return _rwa;
    }

    /// @inheritdoc IPoolStorage
    function rwaDecimals() external view override returns (uint8) {
        return _rwaDecimals;
    }

    /// @inheritdoc IPoolStorage
    function isKYCedBorrower(address account) public view override returns (bool) {
        return _borrowers[account];
    }

    /// @inheritdoc IPoolStorage
    function isKYCedMarketMaker(address account) public view override returns (bool) {
        return _marketMakers[account];
    }

    /// @inheritdoc IPoolStorage
    function spread() external view override returns (uint256) {
        return _spread;
    }

    /// @notice Internal logic to set the leverage.
    function _setLeverage(uint256 leverage) internal {
        require(leverage >= Math.WAD && leverage < MAX_LEVERAGE, Errors.InvalidLeverage());
        _leverage = leverage;
        emit LeverageSet(leverage);
    }

    /// @notice Internal logic to set the spread.
    function _setSpread(uint256 spread_) internal {
        require(spread_ >= MIN_SPREAD, Errors.InvalidSpread());
        _spread = spread_;
        emit SpreadSet(spread_);
    }
}

business_flow_code:
function spread() external view override returns (uint256) {
        return _spread;
    }
function _setSpread(uint256 spread_) internal {
        require(spread_ >= MIN_SPREAD, Errors.InvalidSpread());
        _spread = spread_;
        emit SpreadSet(spread_);
    }
function setSpread(uint256 spread_) external onlyOwner {
        _setSpread(spread_);
    }

business_flow_context:
function swapOut(uint256 id, uint256 rwaAmount) external KycMarketMaker returns (uint256 assetAmount) {
        require(rwaAmount > 0, Errors.ZeroAmount());
        require(_idToMaturity[id].end <= block.timestamp, Errors.TBYNotMatured());

        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        TbyCollateral storage collateral = _idToCollateral[id];
        uint256 currentPrice = _rwaPrice();

        // Cannot swap out more RWA tokens than is allocated for the TBY.
        rwaAmount = Math.min(rwaAmount, collateral.currentRwaAmount);

        if (rwaPrice.endPrice == 0) {
            rwaPrice.endPrice = uint128(currentPrice);
        }

        // If this is the first swap out for the TBY, we need to set the originalRwaAmount to the currentRwaAmount.
        if (collateral.originalRwaAmount == 0) {
            collateral.originalRwaAmount = collateral.currentRwaAmount;
        }

        // Calculate the percentage of RWA tokens that are being currently swapped
        uint256 percentSwapped = rwaAmount.divWad(collateral.originalRwaAmount);
        uint256 percentOfLiquidity = rwaAmount.divWad(collateral.currentRwaAmount);
        require(percentOfLiquidity >= MIN_SWAP_OUT_PERCENT, Errors.SwapOutTooSmall());

        uint256 tbyTotalSupply = _tby.totalSupply(id);
        uint256 tbyAmount = percentSwapped != Math.WAD ? tbyTotalSupply.mulWadUp(percentSwapped) : tbyTotalSupply;
        require(tbyAmount > 0, Errors.ZeroAmount());

        // Calculate the amount of assets that will be swapped out.
        assetAmount = uint256(currentPrice).mulWadUp(rwaAmount) / (10 ** ((18 - _rwaDecimals) + (18 - _assetDecimals)));
        uint256 lenderReturn = getRate(id).mulWad(tbyAmount);

        // If the price has dropped between the end of the TBY's maturity date and when the market maker swap finishes,
        //     only the borrower's returns will be negatively impacted, unless the rate of the drop in price is so large,
        //     that the lender's returns are less than their implied rate. In this case, the rate will be adjusted to
        //     reflect the price of the new assets entering the pool. This adjustment is to ensure that lender returns always
        //     match up with the implied rate of the TBY.
        if (currentPrice < rwaPrice.endPrice) {
            if (lenderReturn > assetAmount) {
                lenderReturn = assetAmount;
                uint256 accumulatedCollateral = _tbyLenderReturns[id] + lenderReturn;
                uint256 remainingAmount =
                    (collateral.currentRwaAmount - rwaAmount).mulWad(currentPrice) / _assetScalingFactor;
                uint256 totalCollateral = accumulatedCollateral + remainingAmount;
                uint256 newRate = totalCollateral.divWad(_tby.totalSupply(id));
                uint256 adjustedRate = _takeSpread(newRate, rwaPrice.spread);
                rwaPrice.endPrice = uint128(adjustedRate.mulWad(rwaPrice.startPrice));
            }
        }
        uint256 borrowerReturn = assetAmount - lenderReturn;

        // Adjust the borrower and lender returns.
        _tbyBorrowerReturns[id] += borrowerReturn;
        _tbyLenderReturns[id] += lenderReturn;

        // Update the collateral for the TBY id.
        collateral.currentRwaAmount -= uint128(rwaAmount);
        collateral.assetAmount += uint128(assetAmount);

        if (collateral.currentRwaAmount == 0) {
            _isTbyRedeemable[id] = true;
        }

        emit MarketMakerSwappedOut(id, msg.sender, rwaAmount, assetAmount);

        IERC20(_asset).safeTransferFrom(msg.sender, address(this), assetAmount);
        IERC20(_rwa).safeTransfer(msg.sender, rwaAmount);
    }
function _setStartPrice(uint256 id, uint256 currentPrice, uint256 rwaAmount, uint256 existingCollateral) private {
        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        uint256 startPrice = rwaPrice.startPrice;
        if (startPrice == 0) {
            rwaPrice.startPrice = uint128(currentPrice);
            rwaPrice.spread = uint128(_spread);
        } else if (startPrice != currentPrice) {
            rwaPrice.startPrice = uint128(_normalizePrice(startPrice, currentPrice, rwaAmount, existingCollateral));
        }
    }
function getRate(uint256 id) public view override returns (uint256) {
        TbyMaturity memory maturity = _idToMaturity[id];
        RwaPrice memory rwaPrice = _tbyIdToRwaPrice[id];

        if (rwaPrice.startPrice == 0) {
            revert Errors.InvalidTby();
        }
        // If the TBY has not started accruing interest, return 1e18.
        if (block.timestamp <= maturity.start) {
            return Math.WAD;
        }

        // If the TBY has matured, and is eligible for redemption, calculate the rate based on the end price.
        uint256 price = rwaPrice.endPrice != 0 ? rwaPrice.endPrice : _rwaPrice();
        uint256 rate = (uint256(price).divWad(uint256(rwaPrice.startPrice)));
        return _takeSpread(rate, rwaPrice.spread);
    }

