function rwa() external view returns (address) {
        return _rwa;
    }
function rwaDecimals() external view override returns (uint8) {
        return _rwaDecimals;
    }

business_flow_context:
function swapIn(address[] memory accounts, uint256 assetAmount)
        external
        KycMarketMaker
        nonReentrant
        returns (uint256 id, uint256 amountSwapped)
    {
        id = _handleTbyId();

        // Iterate through the accounts and convert the matched orders to live TBYs.
        uint256 len = accounts.length;
        for (uint256 i = 0; i != len; ++i) {
            uint256 amountUsed = _convertMatchOrders(id, accounts[i], assetAmount);
            assetAmount -= amountUsed;
            amountSwapped += amountUsed;
            if (assetAmount == 0) break;
        }

        TbyCollateral storage collateral = _idToCollateral[id];
        uint256 currentPrice = _rwaPrice();

        // Calculate the amount of RWA tokens needed to complete the swap.
        uint256 rwaAmount = (amountSwapped * _assetScalingFactor).divWadUp(currentPrice) / _rwaScalingFactor;
        require(rwaAmount > 0, Errors.ZeroAmount());

        // Initalize or normalize the starting price of the TBY.
        _setStartPrice(id, currentPrice, rwaAmount, collateral.currentRwaAmount);

        // Update the collateral for the TBY id.
        collateral.currentRwaAmount += uint128(rwaAmount);

        emit MarketMakerSwappedIn(id, msg.sender, rwaAmount, amountSwapped);

        IERC20(_rwa).safeTransferFrom(msg.sender, address(this), rwaAmount);
        IERC20(_asset).safeTransfer(msg.sender, amountSwapped);
    }
function _setStartPrice(uint256 id, uint256 currentPrice, uint256 rwaAmount, uint256 existingCollateral) private {
        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        uint256 startPrice = rwaPrice.startPrice;
        if (startPrice == 0) {
            rwaPrice.startPrice = uint128(currentPrice);
            rwaPrice.spread = uint128(_spread);
        } else if (startPrice != currentPrice) {
            rwaPrice.startPrice = uint128(_normalizePrice(startPrice, currentPrice, rwaAmount, existingCollateral));
        }
    }
function getRate(uint256 id) public view override returns (uint256) {
        TbyMaturity memory maturity = _idToMaturity[id];
        RwaPrice memory rwaPrice = _tbyIdToRwaPrice[id];

        if (rwaPrice.startPrice == 0) {
            revert Errors.InvalidTby();
        }
        // If the TBY has not started accruing interest, return 1e18.
        if (block.timestamp <= maturity.start) {
            return Math.WAD;
        }

        // If the TBY has matured, and is eligible for redemption, calculate the rate based on the end price.
        uint256 price = rwaPrice.endPrice != 0 ? rwaPrice.endPrice : _rwaPrice();
        uint256 rate = (uint256(price).divWad(uint256(rwaPrice.startPrice)));
        return _takeSpread(rate, rwaPrice.spread);
    }
function setPriceFeed(address rwaPriceFeed_, uint64 priceFeedUpdateInterval_) external onlyOwner {
        _setPriceFeed(rwaPriceFeed_, priceFeedUpdateInterval_);
    }
function _setPriceFeed(address rwaPriceFeed_, uint64 priceFeedUpdateInterval_) internal {
        require(priceFeedUpdateInterval_ != 0, Errors.ZeroAmount());
        (, int256 answer,, uint256 updatedAt,) = AggregatorV3Interface(rwaPriceFeed_).latestRoundData();

        // Validate the latest round data from the price feed.
        require(answer > 0, Errors.InvalidPriceFeed());
        require(updatedAt >= block.timestamp - priceFeedUpdateInterval_, Errors.OutOfDate());

        // Set the price feed for the RWA token.
        _rwaPriceFeed = RwaPriceFeed({
            priceFeed: rwaPriceFeed_,
            updateInterval: priceFeedUpdateInterval_,
            decimals: AggregatorV3Interface(rwaPriceFeed_).decimals()
        });

        emit RwaPriceFeedSet(rwaPriceFeed_);
    }
function rwaPriceFeed() external view returns (RwaPriceFeed memory) {
        return _rwaPriceFeed;
    }
function swapOut(uint256 id, uint256 rwaAmount) external KycMarketMaker returns (uint256 assetAmount) {
        require(rwaAmount > 0, Errors.ZeroAmount());
        require(_idToMaturity[id].end <= block.timestamp, Errors.TBYNotMatured());

        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        TbyCollateral storage collateral = _idToCollateral[id];
        uint256 currentPrice = _rwaPrice();

        // Cannot swap out more RWA tokens than is allocated for the TBY.
        rwaAmount = Math.min(rwaAmount, collateral.currentRwaAmount);

        if (rwaPrice.endPrice == 0) {
            rwaPrice.endPrice = uint128(currentPrice);
        }

        // If this is the first swap out for the TBY, we need to set the originalRwaAmount to the currentRwaAmount.
        if (collateral.originalRwaAmount == 0) {
            collateral.originalRwaAmount = collateral.currentRwaAmount;
        }

        // Calculate the percentage of RWA tokens that are being currently swapped
        uint256 percentSwapped = rwaAmount.divWad(collateral.originalRwaAmount);
        uint256 percentOfLiquidity = rwaAmount.divWad(collateral.currentRwaAmount);
        require(percentOfLiquidity >= MIN_SWAP_OUT_PERCENT, Errors.SwapOutTooSmall());

        uint256 tbyTotalSupply = _tby.totalSupply(id);
        uint256 tbyAmount = percentSwapped != Math.WAD ? tbyTotalSupply.mulWadUp(percentSwapped) : tbyTotalSupply;
        require(tbyAmount > 0, Errors.ZeroAmount());

        // Calculate the amount of assets that will be swapped out.
        assetAmount = uint256(currentPrice).mulWadUp(rwaAmount) / (10 ** ((18 - _rwaDecimals) + (18 - _assetDecimals)));
        uint256 lenderReturn = getRate(id).mulWad(tbyAmount);

        // If the price has dropped between the end of the TBY's maturity date and when the market maker swap finishes,
        //     only the borrower's returns will be negatively impacted, unless the rate of the drop in price is so large,
        //     that the lender's returns are less than their implied rate. In this case, the rate will be adjusted to
        //     reflect the price of the new assets entering the pool. This adjustment is to ensure that lender returns always
        //     match up with the implied rate of the TBY.
        if (currentPrice < rwaPrice.endPrice) {
            if (lenderReturn > assetAmount) {
                lenderReturn = assetAmount;
                uint256 accumulatedCollateral = _tbyLenderReturns[id] + lenderReturn;
                uint256 remainingAmount =
                    (collateral.currentRwaAmount - rwaAmount).mulWad(currentPrice) / _assetScalingFactor;
                uint256 totalCollateral = accumulatedCollateral + remainingAmount;
                uint256 newRate = totalCollateral.divWad(_tby.totalSupply(id));
                uint256 adjustedRate = _takeSpread(newRate, rwaPrice.spread);
                rwaPrice.endPrice = uint128(adjustedRate.mulWad(rwaPrice.startPrice));
            }
        }
        uint256 borrowerReturn = assetAmount - lenderReturn;

        // Adjust the borrower and lender returns.
        _tbyBorrowerReturns[id] += borrowerReturn;
        _tbyLenderReturns[id] += lenderReturn;

        // Update the collateral for the TBY id.
        collateral.currentRwaAmount -= uint128(rwaAmount);
        collateral.assetAmount += uint128(assetAmount);

        if (collateral.currentRwaAmount == 0) {
            _isTbyRedeemable[id] = true;
        }

        emit MarketMakerSwappedOut(id, msg.sender, rwaAmount, assetAmount);

        IERC20(_asset).safeTransferFrom(msg.sender, address(this), assetAmount);
        IERC20(_rwa).safeTransfer(msg.sender, rwaAmount);
    }
function _rwaPrice() private view returns (uint256) {
        RwaPriceFeed memory priceFeed = _rwaPriceFeed;
        (, int256 answer,, uint256 updatedAt,) = AggregatorV3Interface(priceFeed.priceFeed).latestRoundData();

        // Validate the latest round data from the price feed.
        require(answer > 0, Errors.InvalidPriceFeed());
        require(updatedAt >= block.timestamp - priceFeed.updateInterval, Errors.OutOfDate());

        uint256 scaler = 10 ** (18 - priceFeed.decimals);
        return uint256(answer) * scaler;
    }
function swapOut(uint256 id, uint256 rwaAmount) external KycMarketMaker returns (uint256 assetAmount) {
        require(rwaAmount > 0, Errors.ZeroAmount());
        require(_idToMaturity[id].end <= block.timestamp, Errors.TBYNotMatured());

        RwaPrice storage rwaPrice = _tbyIdToRwaPrice[id];
        TbyCollateral storage collateral = _idToCollateral[id];
        uint256 currentPrice = _rwaPrice();

        // Cannot swap out more RWA tokens than is allocated for the TBY.
        rwaAmount = Math.min(rwaAmount, collateral.currentRwaAmount);

        if (rwaPrice.endPrice == 0) {
            rwaPrice.endPrice = uint128(currentPrice);
        }

        // If this is the first swap out for the TBY, we need to set the originalRwaAmount to the currentRwaAmount.
        if (collateral.originalRwaAmount == 0) {
            collateral.originalRwaAmount = collateral.currentRwaAmount;
        }

        // Calculate the percentage of RWA tokens that are being currently swapped
        uint256 percentSwapped = rwaAmount.divWad(collateral.originalRwaAmount);
        uint256 percentOfLiquidity = rwaAmount.divWad(collateral.currentRwaAmount);
        require(percentOfLiquidity >= MIN_SWAP_OUT_PERCENT, Errors.SwapOutTooSmall());

        uint256 tbyTotalSupply = _tby.totalSupply(id);
        uint256 tbyAmount = percentSwapped != Math.WAD ? tbyTotalSupply.mulWadUp(percentSwapped) : tbyTotalSupply;
        require(tbyAmount > 0, Errors.ZeroAmount());

        // Calculate the amount of assets that will be swapped out.
        assetAmount = uint256(currentPrice).mulWadUp(rwaAmount) / (10 ** ((18 - _rwaDecimals) + (18 - _assetDecimals)));
        uint256 lenderReturn = getRate(id).mulWad(tbyAmount);

        // If the price has dropped between the end of the TBY's maturity date and when the market maker swap finishes,
        //     only the borrower's returns will be negatively impacted, unless the rate of the drop in price is so large,
        //     that the lender's returns are less than their implied rate. In this case, the rate will be adjusted to
        //     reflect the price of the new assets entering the pool. This adjustment is to ensure that lender returns always
        //     match up with the implied rate of the TBY.
        if (currentPrice < rwaPrice.endPrice) {
            if (lenderReturn > assetAmount) {
                lenderReturn = assetAmount;
                uint256 accumulatedCollateral = _tbyLenderReturns[id] + lenderReturn;
                uint256 remainingAmount =
                    (collateral.currentRwaAmount - rwaAmount).mulWad(currentPrice) / _assetScalingFactor;
                uint256 totalCollateral = accumulatedCollateral + remainingAmount;
                uint256 newRate = totalCollateral.divWad(_tby.totalSupply(id));
                uint256 adjustedRate = _takeSpread(newRate, rwaPrice.spread);
                rwaPrice.endPrice = uint128(adjustedRate.mulWad(rwaPrice.startPrice));
            }
        }
        uint256 borrowerReturn = assetAmount - lenderReturn;

        // Adjust the borrower and lender returns.
        _tbyBorrowerReturns[id] += borrowerReturn;
        _tbyLenderReturns[id] += lenderReturn;

        // Update the collateral for the TBY id.
        collateral.currentRwaAmount -= uint128(rwaAmount);
        collateral.assetAmount += uint128(assetAmount);

        if (collateral.currentRwaAmount == 0) {
            _isTbyRedeemable[id] = true;
        }

        emit MarketMakerSwappedOut(id, msg.sender, rwaAmount, assetAmount);

        IERC20(_asset).safeTransferFrom(msg.sender, address(this), assetAmount);
        IERC20(_rwa).safeTransfer(msg.sender, rwaAmount);
    }

content:
function openDepth() external view returns (uint256) {
        return _openDepth;
    }

contract_code:
{
    using SafeERC20 for IERC20;
    using Math for uint256;

    /*///////////////////////////////////////////////////////////////
                                Storage    
    //////////////////////////////////////////////////////////////*/

    /// @notice Current total depth of unfilled orders.
    uint256 private _openDepth;

    /// @notice Current total depth of matched orders.
    uint256 internal _matchedDepth;

    /// @notice Mapping of users to their open order amount.
    mapping(address => uint256) private _userOpenOrder;

    /// @notice Mapping of the user's matched orders.
    mapping(address => MatchOrder[]) internal _userMatchedOrders;

    /// @notice Mapping of borrower's to the amount of idle capital they have.
    mapping(address => uint256) private _idleCapital;

    /*///////////////////////////////////////////////////////////////
                            Constructor    
    //////////////////////////////////////////////////////////////*/

    constructor(address asset_, address rwa_, uint256 initLeverage, uint256 initSpread, address owner_)
        PoolStorage(asset_, rwa_, initLeverage, initSpread, owner_)
    {}

    /*///////////////////////////////////////////////////////////////
                            Functions    
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IOrderbook
    function lendOrder(uint256 amount) external {
        _amountZeroCheck(amount);
        _openOrder(msg.sender, amount);
        IERC20(_asset).safeTransferFrom(msg.sender, address(this), amount);
    }

    /// @inheritdoc IOrderbook
    function fillOrder(address account, uint256 amount)
        external
        KycBorrower
        returns (uint256 filledAmount, uint256 borrowAmount)
    {
        (filledAmount, borrowAmount) = _fillOrder(account, amount);
        _depositBorrower(borrowAmount);
    }

    /// @inheritdoc IOrderbook
    function fillOrders(address[] memory accounts, uint256 amount)
        external
        KycBorrower
        returns (uint256 filledAmount, uint256 borrowAmount)
    {
        uint256 len = accounts.length;
        for (uint256 i = 0; i != len; ++i) {
            (uint256 fillSize, uint256 borrowSize) = _fillOrder(accounts[i], amount);
            amount -= fillSize;
            filledAmount += fillSize;
            borrowAmount += borrowSize;
            if (amount == 0) break;
        }
        _depositBorrower(borrowAmount);
    }

    /// @inheritdoc IOrderbook
    function killOpenOrder(uint256 amount) external {
        uint256 orderDepth = _userOpenOrder[msg.sender];
        _amountZeroCheck(amount);
        require(amount <= orderDepth, Errors.InsufficientDepth());

        _userOpenOrder[msg.sender] -= amount;
        _openDepth -= amount;

        emit OpenOrderKilled(msg.sender, amount);
        IERC20(_asset).safeTransfer(msg.sender, amount);
    }

    /// @inheritdoc IOrderbook
    function killMatchOrder(uint256 amount) external returns (uint256 totalRemoved) {
        _amountZeroCheck(amount);
        // if the order is already matched we have to account for the borrower's who filled the order.
        // If you kill a match order and there are multiple borrowers, the order will be closed in a LIFO manner.
        totalRemoved = _closeMatchOrders(msg.sender, amount);
        IERC20(_asset).safeTransfer(msg.sender, totalRemoved);
    }

    /// @inheritdoc IOrderbook
    function killBorrowerMatch(address lender) external returns (uint256 lenderAmount, uint256 borrowerReturn) {
        MatchOrder[] storage matches = _userMatchedOrders[lender];

        uint256 len = matches.length;
        for (uint256 i = 0; i != len; ++i) {
            if (matches[i].borrower == msg.sender) {
                lenderAmount = uint256(matches[i].lCollateral);
                borrowerReturn = uint256(matches[i].bCollateral);
                // Zero out the collateral amounts of the match order to preserve the array's order
                matches[i].lCollateral = 0;
                matches[i].bCollateral = 0;
                // Decrement the matched depth and open move the lenders collateral to an open order.
                _matchedDepth -= lenderAmount;
                _openOrder(lender, lenderAmount);
                break;
            }
        }

        require(lenderAmount != 0, Errors.MatchOrderNotFound());
        emit MatchOrderKilled(lender, msg.sender, lenderAmount);

        IERC20(_asset).safeTransfer(msg.sender, borrowerReturn);
    }

    /// @inheritdoc IOrderbook
    function withdrawIdleCapital(uint256 amount) external {
        address account = msg.sender;
        _amountZeroCheck(amount);

        uint256 idleFunds = _idleCapital[account];

        if (amount == type(uint256).max) {
            amount = idleFunds;
        } else {
            require(idleFunds >= amount, Errors.InsufficientBalance());
        }

        _idleCapital[account] -= amount;
        emit IdleCapitalWithdrawn(account, amount);
        IERC20(_asset).safeTransfer(account, amount);
    }

    /*///////////////////////////////////////////////////////////////
                            Internal Functions    
    //////////////////////////////////////////////////////////////*/

    /**
     * @notice Fills an order with a specified amount of underlying assets
     * @param account The address of the order to fill
     * @param amount Amount of underlying assets of the order to fill
     */
    function _fillOrder(address account, uint256 amount) internal returns (uint256 filled, uint256 borrowAmount) {
        require(account != address(0), Errors.ZeroAddress());
        _amountZeroCheck(amount);

        uint256 orderDepth = _userOpenOrder[account];

        filled = Math.min(orderDepth, amount);
        _openDepth -= filled;
        _matchedDepth += filled;
        _userOpenOrder[account] -= filled;

        borrowAmount = filled.divWad(_leverage);

        MatchOrder[] storage matches = _userMatchedOrders[account];
        uint256 len = matches.length;

        for (uint256 i = 0; i != len; ++i) {
            if (matches[i].borrower == msg.sender) {
                matches[i].lCollateral += uint128(filled);
                matches[i].bCollateral += uint128(borrowAmount);
                emit OrderFilled(account, msg.sender, _leverage, filled);
                return (filled, borrowAmount);
            }
        }

        matches.push(
            MatchOrder({lCollateral: uint128(filled), bCollateral: uint128(borrowAmount), borrower: msg.sender})
        );
        emit OrderFilled(account, msg.sender, _leverage, filled);
    }

    /**
     * @notice Opens an order for the lender
     * @param lender The address of the lender
     * @param amount The amount of underlying assets to open the order
     */
    function _openOrder(address lender, uint256 amount) internal {
        _openDepth += amount;
        _userOpenOrder[lender] += amount;
        emit OrderCreated(lender, amount);
    }

    /**
     * @notice Deposits the leveraged matched amount of underlying assets from the borrower
     * @dev If the borrower has idle capital, it will be used to match the order first before depositing
     * @param amount Amount of underlying assets matched by the borrower
     */
    function _depositBorrower(uint256 amount) internal {
        amount = _utilizeIdleCapital(msg.sender, amount);
        require(IERC20(_asset).balanceOf(msg.sender) >= amount, Errors.InsufficientBalance());

        IERC20(_asset).safeTransferFrom(msg.sender, address(this), amount);
    }

    function _utilizeIdleCapital(address account, uint256 amount) internal returns (uint256) {
        uint256 idleUsed = Math.min(_idleCapital[account], amount);
        if (idleUsed > 0) {
            _idleCapital[account] -= idleUsed;
            amount -= idleUsed;
            emit IdleCapitalDecreased(account, idleUsed);
        }
        return amount;
    }

    /**
     * @notice Closes matched orders for the user
     * @dev Orders are closed in a LIFO manner
     * @param amount The amount of underlying assets to close the matched order
     * @return totalRemoved The amount for each borrower that was removed.
     */
    function _closeMatchOrders(address account, uint256 amount) internal returns (uint256 totalRemoved) {
        MatchOrder[] storage matches = _userMatchedOrders[account];
        uint256 remainingAmount = amount;

        uint256 length = matches.length;
        for (uint256 i = length; i != 0; --i) {
            uint256 index = i - 1;

            // If the match order is already closed, remove it from the array
            if (matches[index].lCollateral == 0) {
                matches.pop();
                continue;
            }

            if (remainingAmount != 0) {
                uint256 amountToRemove = Math.min(remainingAmount, matches[index].lCollateral);
                uint256 borrowAmount = uint256(matches[index].bCollateral);

                if (amountToRemove != matches[index].lCollateral) {
                    borrowAmount = amountToRemove.divWad(_leverage);
                    matches[index].lCollateral -= uint128(amountToRemove);
                    matches[index].bCollateral -= uint128(borrowAmount);
                }
                remainingAmount -= amountToRemove;
                _idleCapital[matches[index].borrower] += borrowAmount;

                emit MatchOrderKilled(account, matches[index].borrower, amountToRemove);
                if (matches[index].lCollateral == amountToRemove) matches.pop();
            } else {
                break;
            }
        }
        totalRemoved = amount - remainingAmount;
        _matchedDepth -= totalRemoved;
    }

    /**
     * @notice Checks if the amount is greater than zero
     * @param amount The amount of underlying assets to close the matched order
     */
    function _amountZeroCheck(uint256 amount) internal pure {
        require(amount > 0, Errors.ZeroAmount());
    }

    /*///////////////////////////////////////////////////////////////
                            View Functions    
    //////////////////////////////////////////////////////////////*/

    /// @inheritdoc IOrderbook
    function leverage() external view override returns (uint256) {
        return _leverage;
    }

    /// @inheritdoc IOrderbook
    function openDepth() external view returns (uint256) {
        return _openDepth;
    }

    /// @inheritdoc IOrderbook
    function matchedDepth() external view returns (uint256) {
        return _matchedDepth;
    }

    /// @inheritdoc IOrderbook
    function amountOpen(address account) external view returns (uint256) {
        return _userOpenOrder[account];
    }

    /// @inheritdoc IOrderbook
    function amountMatched(address account) external view returns (uint256 amount) {
        uint256 len = _userMatchedOrders[account].length;
        for (uint256 i = 0; i != len; ++i) {
            amount += _userMatchedOrders[account][i].lCollateral;
        }
    }

    /// @inheritdoc IOrderbook
    function matchedOrder(address account, uint256 index) external view returns (MatchOrder memory) {
        return _userMatchedOrders[account][index];
    }

    /// @inheritdoc IOrderbook
    function matchedOrderCount(address account) external view returns (uint256) {
        return _userMatchedOrders[account].length;
    }

    /// @inheritdoc IOrderbook
    function idleCapital(address account) external view returns (uint256) {
        return _idleCapital[account];
    }
}

business_flow_code:
function _openOrder(address lender, uint256 amount) internal {
        _openDepth += amount;
        _userOpenOrder[lender] += amount;
        emit OrderCreated(lender, amount);
    }
function lendOrder(uint256 amount) external {
        _amountZeroCheck(amount);
        _openOrder(msg.sender, amount);
